p='src/app.ts'
s=open(p).read()
s=s.replace('import { pool } from "./db.ts";','import { pool } from "./db.ts";\nimport { payments } from "./payments.ts";')
route='''  app.post("/orders/:id/refund", async (req, res) => {
    const user = res.locals.user;
    const rawId = String(req.params.id);
    const id = /^\\d{1,9}$/.test(rawId) ? Number(rawId) : NaN;
    if (!Number.isSafeInteger(id) || id < 1) return sendError(res, 400, "invalid_id", "Order id must be a positive integer");

    // Owners and admins only; anyone else sees the same 404 as a missing order.
    const { rows } = await pool.query(
      "select id, status, total_cents, payment_id from orders where id = $1 and ($3 or user_id = $2)",
      [id, user.id, user.role === "admin"],
    );
    const order = rows[0];
    if (!order) return sendError(res, 404, "not_found", "Order not found");
    if (order.status !== "paid" || !order.payment_id) {
      return sendError(res, 409, "not_refundable", "Only paid orders can be refunded");
    }

    // Provider call is outside any transaction. The key comes from the order, so concurrent or retried
    // requests (including after a crash before the update below) refund once.
    try {
      await payments.refund({
        paymentId: order.payment_id,
        amountCents: order.total_cents,
        idempotencyKey: `refund-order-${order.id}`,
      });
    } catch (err) {
      console.error(err);
      return sendError(res, 502, "refund_failed", "Refund failed");
    }

    // Only move paid -> refunded. If a concurrent request already did, the result is the same.
    await pool.query("update orders set status = 'refunded' where id = $1 and status = 'paid'", [id]);
    res.json({ id: order.id, status: "refunded", total_cents: order.total_cents });
  });

'''
